1	/**
2	 * #{#sec1b} Signed URL Utility
3	 *
4	 * Centralizes signed URL generation for the receipts storage bucket.
5	 * Replaces all getPublicUrl() calls with time-limited signed URLs.
6	 */
7	
8	import { supabase } from '$lib/supabaseClient';
9	import { collectSignedUrls } from './signedUrlBatch';
10	
11	/** Default signed URL expiry: 1 hour */
12	const DEFAULT_EXPIRY_SECONDS = 3600;
13	
14	/**
15	 * Generate a signed URL for a file in the receipts storage bucket.
16	 *
17	 * @param path - Storage path (e.g. "user-id/filename.jpg")
18	 * @param expiresIn - URL lifetime in seconds (default: 3600)
19	 * @returns Signed URL string, or null if path is empty or generation fails
20	 */
21	export async function getSignedReceiptUrl(
22		path: string | null | undefined,
23		expiresIn: number = DEFAULT_EXPIRY_SECONDS
24	): Promise<string | null> {
25		if (!path) return null;
26	
27		const { data, error } = await supabase.storage.from('receipts').createSignedUrl(path, expiresIn);
28	
29		if (error) {
30			console.error('Failed to create signed URL for path:', path, 'error:', error.message);
31			return null;
32		}
33	
34		return data.signedUrl;
35	}
36	
37	/**
38	 * #{#sec1c} Generate signed URLs for many receipt paths in one shot.
39	 *
40	 * Replaces N per-path createSignedUrl round trips with a few chunked
41	 * createSignedUrls batch calls. Returns a path→signedUrl map containing only the
42	 * paths that signed successfully; failures are dropped soft (see collectSignedUrls).
43	 *
44	 * @param paths - Storage paths (duplicates and empties are ignored)
45	 * @param expiresIn - URL lifetime in seconds (default: 3600)
46	 */
47	export async function getSignedReceiptUrls(
48		paths: string[],
49		expiresIn: number = DEFAULT_EXPIRY_SECONDS
50	): Promise<Record<string, string>> {
51		return collectSignedUrls(paths, async (batch) => {
52			const { data, error } = await supabase.storage
53				.from('receipts')
54				.createSignedUrls(batch, expiresIn);
55			if (error) throw error;
56			return data ?? [];
57		});
58	}
