1	import { fileTypeFromBuffer } from 'file-type';
2	
3	export type FileCategory = 'pdf' | 'image';
4	
5	export interface FileValidationResult {
6		isValid: boolean;
7		mimeType?: string;
8		category?: FileCategory;
9		error?: string;
10	}
11	
12	export class FileValidator {
13		private static readonly MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB
14	
15		private static readonly SUPPORTED_TYPES = {
16			PDF: ['application/pdf'],
17			IMAGE: ['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/heic', 'image/heif']
18		} as const;
19	
20		/**
21		 * Validates a file buffer by checking its magic numbers (file signature)
22		 * This prevents users from simply renaming files to bypass validation
23		 */
24		static async validateFile(buffer: Buffer): Promise<FileValidationResult> {
25			// Check file size
26			if (buffer.length > this.MAX_FILE_SIZE) {
27				return {
28					isValid: false,
29					error: `File size exceeds ${this.MAX_FILE_SIZE / 1024 / 1024}MB limit`
30				};
31			}
32	
33			// Detect actual file type from magic numbers
34			const detectedType = await fileTypeFromBuffer(buffer);
35	
36			if (!detectedType) {
37				return {
38					isValid: false,
39					error: 'Could not determine file type. The file may be corrupted or unsupported.'
40				};
41			}
42	
43			// Validate against whitelist
44			const category = this.categorizeMimeType(detectedType.mime);
45	
46			if (!category) {
47				const supported = [...this.SUPPORTED_TYPES.PDF, ...this.SUPPORTED_TYPES.IMAGE].join(', ');
48	
49				return {
50					isValid: false,
51					error: `File type ${detectedType.mime} is not supported. Supported types: ${supported}`
52				};
53			}
54	
55			return {
56				isValid: true,
57				mimeType: detectedType.mime,
58				category
59			};
60		}
61	
62		/**
63		 * Categorizes a MIME type into pdf or image
64		 */
65		private static categorizeMimeType(mimeType: string): FileCategory | null {
66			const normalized = mimeType.toLowerCase();
67	
68			if ((this.SUPPORTED_TYPES.PDF as readonly string[]).includes(normalized)) {
69				return 'pdf';
70			}
71	
72			if ((this.SUPPORTED_TYPES.IMAGE as readonly string[]).includes(normalized)) {
73				return 'image';
74			}
75	
76			return null;
77		}
78	
79		/**
80		 * Get list of supported MIME types
81		 */
82		static getSupportedTypes(): string[] {
83			return [...this.SUPPORTED_TYPES.PDF, ...this.SUPPORTED_TYPES.IMAGE];
84		}
85	}
