1	// Testable core of the Resend webhook handler.
2	//
3	// This module holds the handler's ENTIRE request→response orchestration as an
4	// exported async function with all collaborators injected via `deps`. It is the
5	// "functional core, imperative shell" split from the PRD: `index.ts` keeps the
6	// one-line `Deno.serve` binding (the untested shell that wires real deps), while
7	// everything branchy lives here so it can be exercised under vitest with no
8	// network, no live Supabase, and no Deno runtime.
9	//
10	// Nothing in this file imports svix, @supabase/supabase-js as a value, or calls
11	// Deno.serve / Deno.env / global fetch directly — those all arrive through
12	// `WebhookDeps`. The only non-type import from those packages is `SupabaseClient`
13	// as a pure type (erased by the bundler), so loading this module is side-effect
14	// free.
15	
16	import type { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2';
17	import { type OcrResult } from '../_shared/mistral.ts';
18	import {
19		resolveEmailReceiptDate,
20		type EmailReceiptDateResult
21	} from '../_shared/emailReceiptDate.ts';
22	import {
23		isSupportedReceiptType,
24		isInlineAttachment,
25		hasUsableOcrData,
26		hasSupportedAttachments
27	} from '../_shared/attachmentFiltering.ts';
28	import {
29		sendNotificationEmail as sendResendNotification,
30		type NotificationType
31	} from '../_shared/notify.ts';
32	import { parseSenderEmail } from '../_shared/emailParsing.ts';
33	import { errText } from '../_shared/errText.ts';
34	
35	interface ResendAttachmentMetadata {
36		id: string;
37		filename: string;
38		content_type: string;
39		content_disposition?: string;
40		content_id?: string;
41	}
42	
43	interface ResendWebhookEvent {
44		type: string;
45		created_at: string;
46		data: {
47			email_id: string;
48			from: string;
49			to: string[];
50			subject: string;
51			created_at: string;
52			message_id: string;
53			bcc: string[];
54			cc: string[];
55			attachments: ResendAttachmentMetadata[];
56		};
57	}
58	
59	interface ResendEmail {
60		email_id: string;
61		from: string;
62		to: string[];
63		subject: string;
64		html: string | null;
65		text: string | null;
66		headers: Record<string, string>;
67	}
68	
69	interface ResendAttachment {
70		filename: string;
71		content_type: string;
72		size: number;
73		download_url: string;
74		expires_at: string;
75		// Present on the download-URL response; used to skip inline attachments.
76		content_id?: string;
77		content_disposition?: string;
78	}
79	
80	/** The receipt row insert helpers return (only these fields are read). */
81	interface InsertedReceipt {
82		id?: string;
83		merchant_name?: string | null;
84		total_amount?: number | null;
85		[key: string]: unknown;
86	}
87	
88	/**
89	 * OCR collaborator. The real implementation is Mistral (`../_shared/mistral.ts`);
90	 * tests inject stubs. Keeping the three calls behind one port means the handler
91	 * never reaches the network for OCR.
92	 */
93	export interface OcrPort {
94		processEmailText(emailText: string): Promise<OcrResult | null>;
95		textToImage(text: string): Promise<Uint8Array>;
96		ocrFromUrl(fileUrl: string, mimeType: string): Promise<OcrResult>;
97	}
98	
99	/**
100	 * Every side-effecting collaborator the handler needs. The shell builds this
101	 * from the real Deno runtime; tests build it from in-memory fakes.
102	 */
103	export interface WebhookDeps {
104		/** Service-role client — rpc(), from().insert(), storage.upload()/createSignedUrl(). */
105		supabase: SupabaseClient;
106		/** Used for Resend email content, attachment downloads, and the notification send. */
107		fetchFn: typeof fetch;
108		/** Replaces inline `Deno.env.get()`. */
109		env: (key: string) => string | undefined;
110		/** Replaces `new Date()` — makes suspicious-date checks and timestamps deterministic. */
111		now: () => Date;
112		/** OCR collaborator (Mistral in production). */
113		ocr: OcrPort;
114		/** Best-effort foreign-currency rate lookup (Bank of Canada in production). */
115		exchangeRate: (currency: string, date: string) => Promise<number | null>;
116		/** Verifies the Resend/Svix webhook signature. Kept out of the core so svix stays in the shell. */
117		verifySignature: (headers: Headers, payload: string, signingSecret: string) => boolean;
118	}
