127	async function uploadToStorage(
128		supabase: SupabaseClient,
129		userId: string,
130		bytes: Uint8Array,
131		contentType: string,
132		ext: string
133	): Promise<{ path: string; signedUrl: string }> {
134		const path = `${userId}/${crypto.randomUUID()}.${ext}`;
135		const { error } = await supabase.storage
136			.from('receipts')
137			.upload(path, bytes, { contentType, upsert: false });
138		if (error) throw error;
139		// #{#sec1b} Use signed URL — receipts bucket is private (#{#sec1a})
140		// 5-minute expiry matches OCR signed URL pattern in ReceiptService.ts
141		const { data, error: signError } = await supabase.storage
142			.from('receipts')
143			.createSignedUrl(path, 300);
144		if (signError) throw signError;
145		return { path, signedUrl: data.signedUrl };
146	}
