148	// #{#fcr1a} #{#fcr2a} Best-effort exchange rate lookup for foreign currency receipts.
149	// Returns null if currency is CAD/unknown, date is missing, or the API call fails —
150	// matches ReceiptService.uploadAndCreate so the receipt still saves without a rate.
151	async function fetchRateForReceipt(
152		exchangeRate: WebhookDeps['exchangeRate'],
153		currency: string | null | undefined,
154		transactionDate: string | null | undefined
155	): Promise<number | null> {
156		if (!currency || currency === 'CAD' || !transactionDate) return null;
157		try {
158			return await exchangeRate(currency, transactionDate);
159		} catch (err) {
160			console.error('Exchange rate fetch failed:', err);
161			return null;
162		}
163	}
