165	async function insertReceipt(
166		supabase: SupabaseClient,
167		receiptData: Record<string, unknown>
168	): Promise<InsertedReceipt | null> {
169		console.log('Attempting to insert receipt with RPC...');
170		// Use RPC to insert with proper user context
171		const { data, error } = await supabase.rpc('insert_receipt_with_context', {
172			receipt_data: receiptData
173		});
174	
175		if (error) {
176			console.error('RPC insert failed:', JSON.stringify(error, null, 2));
177			console.log('Falling back to direct insert...');
178	
179			// Fallback to direct insert - bypass RLS with service role
180			const { data: directData, error: directError } = await supabase
181				.from('receipts')
182				.insert(receiptData)
183				.select('*')
184				.single();
185	
186			if (directError) {
187				console.error('Direct insert also failed:', JSON.stringify(directError, null, 2));
188				throw directError;
189			}
190			console.log('Direct insert succeeded');
191			return directData;
192		}
193	
194		console.log('RPC insert succeeded');
195		return data;
196	}
