198	/**
199	 * Persist a failed notification send so the failure is not silent.
200	 *
201	 * The notification channel (email) is the thing that broke, so we can't email
202	 * the user to tell them email failed. Instead we record it in
203	 * `email_send_failures`: the row is family-scoped (RLS) so the user sees an
204	 * in-app notice, and it doubles as the admin alert feed. Best-effort — a
205	 * logging failure must never break webhook processing.
206	 */
207	async function recordNotificationFailure(
208		supabase: SupabaseClient,
209		params: {
210			userId: string;
211			recipient: string;
212			notificationType: NotificationType;
213			originalSubject: string;
214			emailId?: string;
215			statusCode: number;
216			error: string;
217		}
218	): Promise<void> {
219		try {
220			const { error } = await supabase.from('email_send_failures').insert({
221				user_id: params.userId,
222				recipient: params.recipient,
223				notification_type: params.notificationType,
224				original_subject: params.originalSubject,
225				resend_email_id: params.emailId ?? null,
226				status_code: params.statusCode,
227				error: params.error
228			});
229			if (error) {
230				console.error('Failed to record notification failure:', JSON.stringify(error));
231			} else {
232				console.log(`Recorded notification failure for ${params.recipient} (admin alert queued)`);
233			}
234		} catch (err) {
235			console.error('Exception recording notification failure:', err);
236		}
237	}
