239	/**
240	 * Send a notification email and, if the send fails, record it durably so the
241	 * failure surfaces to the user (in-app) and to admins instead of vanishing into
242	 * the logs. Wraps the extracted `sendResendNotification` sender, threading the
243	 * injected fetch/env/clock so it stays isolated from the network in tests.
244	 */
245	async function sendNotificationEmail(
246		deps: WebhookDeps,
247		userId: string,
248		apiKey: string,
249		toEmail: string,
250		notificationType: NotificationType,
251		title: string,
252		message: string,
253		originalSubject: string,
254		emailId?: string
255	): Promise<void> {
256		const result = await sendResendNotification(
257			apiKey,
258			toEmail,
259			notificationType,
260			title,
261			message,
262			originalSubject,
263			emailId,
264			{ fetchFn: deps.fetchFn, env: deps.env, now: deps.now }
265		);
266	
267		if (!result.ok) {
268			await recordNotificationFailure(deps.supabase, {
269				userId,
270				recipient: toEmail,
271				notificationType,
272				originalSubject,
273				emailId,
274				statusCode: result.status,
275				error: result.error ?? 'Unknown send failure'
276			});
277		}
278	}
