280	/**
281	 * The Resend webhook handler, fully injectable. Behaviour is identical to the
282	 * previous inline `Deno.serve` body — every `Deno.env.get` / global `fetch` /
283	 * `createClient` / `new Date()` / Mistral / exchange-rate / signature call is
284	 * routed through `deps`.
285	 */
286	export async function handleResendWebhook(req: Request, deps: WebhookDeps): Promise<Response> {
287		console.log('=== Resend Webhook Request Received ===');
288		console.log('Method:', req.method);
289		console.log('URL:', req.url);
290	
291		if (req.method !== 'POST') {
292			console.log('Rejecting non-POST request');
293			return jsonResponse(405, { error: 'Method not allowed' });
294		}
295	
296		// Read the raw body for signature verification
297		const bodyText = await req.text();
298		console.log('Received webhook payload length:', bodyText.length);
299		console.log('Raw payload:', bodyText.substring(0, 500) + (bodyText.length > 500 ? '...' : ''));
300	
301		let event: ResendWebhookEvent;
302	
303		try {
304			event = JSON.parse(bodyText);
305			console.log('Parsed event type:', event.type);
306			console.log('Event data:', JSON.stringify(event.data));
307		} catch (e) {
308			console.error('Failed to parse JSON:', e);
309			return jsonResponse(400, { error: 'Invalid JSON' });
310		}
311	
312		// Basic validation
313		if (!event.type) {
314			console.error('Missing event type in payload');
315			return jsonResponse(400, { error: 'Missing event type' });
316		}
317	
318		const supabaseUrl = deps.env('SUPABASE_URL');
319		const serviceRoleKey = deps.env('SUPABASE_SERVICE_ROLE_KEY');
320		const resendApiKey = deps.env('RESEND_API_KEY');
321		const resendWebhookSecret = deps.env('RESEND_WEBHOOK_SECRET');
322	
323		if (!supabaseUrl || !serviceRoleKey) {
324			return jsonResponse(500, { error: 'Missing Supabase env' });
325		}
326		if (!resendApiKey) {
327			console.error('RESEND_API_KEY environment variable is not set');
328			return jsonResponse(500, { error: 'Missing Resend API key' });
329		}
330	
331		console.log(`Resend API key is set (length: ${resendApiKey.length})`);
332	
333		// Log all request headers for debugging
334		console.log('Request headers:', JSON.stringify(Object.fromEntries(req.headers.entries())));
335	
336		// Verify the webhook signature — FAIL CLOSED. This endpoint runs with the
337		// service role and inserts receipts keyed on the sender's email, so an
338		// unauthenticated caller could forge an `email.received` event and inject
339		// receipts into any user's account (bypassing RLS). A missing secret is a
340		// server misconfiguration (500); a bad/absent signature is rejected (401).
341		// Never log the secret value.
342		if (!resendWebhookSecret) {
343			console.error('RESEND_WEBHOOK_SECRET is not set — refusing to process unverified webhook');
344			return jsonResponse(500, { error: 'Webhook signing secret not configured' });
345		}
346		if (!deps.verifySignature(req.headers, bodyText, resendWebhookSecret)) {
347			console.error('Invalid webhook signature — rejecting request');
348			return jsonResponse(401, { error: 'Invalid webhook signature' });
349		}
350		console.log('Webhook signature verification passed');
351	
352		// Only process email.received events
353		if (event.type !== 'email.received') {
354			console.log(`Ignoring event type: ${event.type} - returning success`);
355			return jsonResponse(200, { message: `Event type ${event.type} ignored` });
356		}
357	
358		console.log('Processing email.received event...');
359	
360		const supabase = deps.supabase;
361	
362		// Find user by sender email. Resend delivers `from` as either a bare address
363		// or `Display Name <addr>` — extract the address so the exact-match lookup
364		// works regardless of the forwarding client's formatting.
365		const sender = parseSenderEmail(event.data?.from);
366		if (!sender) {
367			console.error('Missing or unparseable sender in event data:', event.data?.from);
368			return jsonResponse(400, { error: 'Missing sender' });
369		}
370	
371		console.log(`Looking up user by email: ${sender}`);
372		const { data: userIdData, error: userErr } = await supabase.rpc('find_user_by_email', {
373			email_address: sender
374		});
375		if (userErr) {
376			console.error(`Error finding user: ${JSON.stringify(userErr)}`);
377			return jsonResponse(500, { error: userErr.message });
378		}
379		if (!userIdData) {
380			console.error(`No user found for email: ${sender}`);
381			return jsonResponse(404, { error: 'User not found for sender email' });
382		}
383		const userId = userIdData as string;
384		console.log(`Found user ID: ${userId}`);
385	
386		// Fetch the full email content from Resend API to get body text
387		console.log(`Fetching email content for email_id: ${event.data.email_id}`);
388		console.log(
389			`Using API key: ${resendApiKey.substring(0, 7)}...${resendApiKey.substring(resendApiKey.length - 4)}`
390		);
391		console.log(`API endpoint: https://api.resend.com/emails/receiving/${event.data.email_id}`);
392	
393		let emailBodyText = '';
394	
395		try {
396			const emailResponse = await deps.fetchFn(
397				`https://api.resend.com/emails/receiving/${event.data.email_id}`,
398				{
399					method: 'GET',
400					headers: {
401						Authorization: `Bearer ${resendApiKey}`,
402						'Content-Type': 'application/json'
403					}
404				}
405			);
406	
407			console.log(`Email fetch response status: ${emailResponse.status}`);
408	
409			if (!emailResponse.ok) {
410				const errorText = await emailResponse.text();
411				console.error(`Failed to fetch email: ${emailResponse.status} ${emailResponse.statusText}`);
412				console.error(`Error response body: ${errorText}`);
413				// Don't return error - continue with attachments processing
414			} else {
415				const email: ResendEmail = await emailResponse.json();
416				console.log(
417					`Email fetched successfully. Has text: ${!!email.text}, Has html: ${!!email.html}`
418				);
419				emailBodyText = (email.text || email.html || '').toString();
420			}
421		} catch (e) {
422			console.error('Exception fetching email content:', e);
423			// Continue processing - we can still try attachments
424		}
425	
426		// Single null-date handler shared by every insert path below: resolve the
427		// date (receipt date -> forwarded-email fallback -> none) and notify the user
428		// on a suspicious or missing date. Hoisted so all three paths behave alike.
429		const resolveDateAndNotify = async (
430			extracted: OcrResult,
431			filename?: string
432		): Promise<EmailReceiptDateResult> => {
433			const result = resolveEmailReceiptDate(
434				extracted.transaction_date ?? null,
435				extracted.raw_date_text ?? null,
436				emailBodyText,
437				deps.now()
438			);
439			extracted.transaction_date = result.transaction_date;
440	
441			const src = filename ? ` from "${filename}"` : '';
442			if (result.suspicious_date) {
443				console.log(`Suspicious date for email receipt${src}: ${result.transaction_date}`);
444				await sendNotificationEmail(
445					deps,
446					userId,
447					resendApiKey,
448					sender,
449					'warning',
450					'Please Check Receipt Date',
451					`The receipt date we found (${result.transaction_date})${src} seems unusual - it's either more than 6 weeks old or in the future. We've saved the receipt, but please verify the date is correct and update it if needed.`,
452					event.data.subject,
453					event.data.email_id
454				);
455			} else if (result.dateSource === 'none') {
456				console.log(`No date found for email receipt${src}; saving without a date`);
457				await sendNotificationEmail(
458					deps,
459					userId,
460					resendApiKey,
461					sender,
462					'warning',
463					'Receipt Saved Without a Date',
464					`We couldn't find a date for your receipt${src}. We've saved it, but please open it in your expense tracker and add the correct date.`,
465					event.data.subject,
466					event.data.email_id
467				);
468			}
469			return result;
470		};
471	
472		// #{#eaf5a} Check for supported attachments before processing body text
473		const attachmentMetadata = event.data.attachments || [];
474		const hasScannable = hasSupportedAttachments(attachmentMetadata);
475	
476		let inserted: InsertedReceipt | null = null;
477		const processingErrors: string[] = [];
478	
479		// #{#eaf5a} Only process body text if no supported attachments exist
480		if (emailBodyText && !hasScannable) {
481			console.log('No supported attachments found, processing email body text');
482		} else if (hasScannable) {
483			console.log(
484				`Skipping body text extraction — ${attachmentMetadata.length} supported attachment(s) found`
485			);
486		}
487	
488		if (emailBodyText && !hasScannable) {
489			try {
490				console.log('Processing email body text with Mistral...');
491				const extracted = await deps.ocr.processEmailText(emailBodyText);
492	
493				if (extracted) {
494					console.log('Mistral found receipt data:', JSON.stringify(extracted, null, 2));
495	
496					// Convert the text to an image
497					console.log('Converting text to image...');
498					const imageBytes = await deps.ocr.textToImage(emailBodyText);
499					const { path, signedUrl } = await uploadToStorage(
500						supabase,
501						userId,
502						imageBytes,
503						'image/svg+xml',
504						'svg'
505					);
506					console.log('Image uploaded to:', signedUrl);
507	
508					// Insert receipt with the text-as-image
509					try {
510						console.log('Inserting receipt for user:', userId);
511	
512						// Resolve the date and notify on a suspicious/missing date (shared handler).
513						const dateResult = await resolveDateAndNotify(extracted);
514	
515						// #{#fcr1a} #{#fcr2a} Fetch exchange rate for foreign currency receipts
516						const exchangeRate = await fetchRateForReceipt(
517							deps.exchangeRate,
518							extracted.currency,
519							extracted.transaction_date
520						);
521	
522						inserted = await insertReceipt(supabase, {
523							user_id: userId,
524							receipt_image_path: path,
525							merchant_name: extracted.merchant_name,
526							total_amount: extracted.total_amount,
527							tax: extracted.tax,
528							transaction_date: extracted.transaction_date,
529							currency: extracted.currency,
530							exchange_rate_to_cad: exchangeRate,
531							credit_card_name: extracted.credit_card_name,
532							credit_card_last_4: extracted.credit_card_last_4,
533							suspicious_date: dateResult.suspicious_date
534						});
535						console.log('Receipt inserted successfully:', inserted?.id);
536					} catch (insertErr) {
537						const msg = `Body text insert failed: ${errText(insertErr)}`;
538						console.error(msg);
539						processingErrors.push(msg);
540					}
541				} else {
542					console.log('No receipt data found in email body text');
543					// Don't send notification yet - we'll try attachments first
544				}
545			} catch (e) {
546				const msg = `Body text processing error: ${errText(e)}`;
547				console.error(msg);
548				processingErrors.push(msg);
549			}
550		}
551	
552		// Process attachments (either as primary path or fallback from body text)
553		if (!inserted) {
554			console.log(`Found ${attachmentMetadata.length} attachment(s) in webhook payload`);
555	
556			if (attachmentMetadata.length === 0) {
557				console.log('No attachments to process');
558			} else {
559				// Fetch attachment download URLs from Resend API
560				console.log(`Fetching attachment download URLs for email_id: ${event.data.email_id}`);
561	
562				try {
563					const attachmentsResponse = await deps.fetchFn(
564						`https://api.resend.com/emails/receiving/${event.data.email_id}/attachments`,
565						{
566							method: 'GET',
567							headers: {
568								Authorization: `Bearer ${resendApiKey}`,
569								'Content-Type': 'application/json'
570							}
571						}
572					);
573	
574					console.log(`Attachments fetch response status: ${attachmentsResponse.status}`);
575	
576					if (!attachmentsResponse.ok) {
577						const errorText = await attachmentsResponse.text();
578						const msg = `Resend attachment fetch failed: ${attachmentsResponse.status} ${attachmentsResponse.statusText} — ${errorText}`;
579						console.error(msg);
580						processingErrors.push(msg);
581					} else {
582						const attachmentsData = await attachmentsResponse.json();
583						console.log(`Attachments response data: ${JSON.stringify(attachmentsData)}`);
584						const attachments: ResendAttachment[] = attachmentsData.data || [];
585	
586						console.log(`Received ${attachments.length} attachment download URL(s)`);
587	
588						let processedCount = 0;
589	
590						for (const att of attachments) {
591							try {
592								// #{#eaf2a} Skip inline attachments (signatures, logos)
593								if (
594									isInlineAttachment({
595										filename: att.filename,
596										content_type: att.content_type,
597										content_id: att.content_id,
598										content_disposition: att.content_disposition
599									})
600								) {
601									console.log(
602										`Skipping inline attachment: ${att.filename} (content_id: ${att.content_id})`
603									);
604									continue;
605								}
606	
607								// #{#eaf1a} Filter by supported MIME types
608								const ct = att.content_type || 'application/octet-stream';
609								if (!isSupportedReceiptType(ct, att.filename)) {
610									console.log(`Skipping unsupported attachment type: ${ct} (${att.filename})`);
611									continue;
612								}
613	
614								console.log(`Processing attachment: ${att.filename}`);
615	
616								// Download attachment using the provided download_url
617								const downloadResponse = await deps.fetchFn(att.download_url);
618								if (!downloadResponse.ok) {
619									const msg = `Download failed for ${att.filename}: HTTP ${downloadResponse.status}`;
620									console.error(msg);
621									processingErrors.push(msg);
622	
623									// Notify user about attachment download failure
624									await sendNotificationEmail(
625										deps,
626										userId,
627										resendApiKey,
628										sender,
629										'error',
630										'Attachment Download Failed',
631										`We couldn't download the attachment "${att.filename}" from your email. Resend attachments expire after 30 minutes, so the download link may have expired. Please try forwarding the email again.`,
632										event.data.subject,
633										event.data.email_id
634									);
635	
636									continue;
637								}
638	
639								const bytes = new Uint8Array(await downloadResponse.arrayBuffer());
640								const ext = (att.filename?.split('.')?.pop() || 'bin').toLowerCase();
641	
642								const { path, signedUrl } = await uploadToStorage(supabase, userId, bytes, ct, ext);
643								const extracted = await deps.ocr.ocrFromUrl(signedUrl, ct).catch(async (err) => {
644									const msg = `OCR failed for ${att.filename}: ${err?.message || err}`;
645									console.error(msg);
646									processingErrors.push(msg);
647	
648									// Notify user about OCR failure
649									await sendNotificationEmail(
650										deps,
651										userId,
652										resendApiKey,
653										sender,
654										'error',
655										'Receipt Reading Failed',
656										`We couldn't extract receipt information from "${att.filename}". The image or PDF may be unclear, too dark, or rotated. Please try sending a clearer, well-lit photo of the receipt.`,
657										event.data.subject,
658										event.data.email_id
659									);
660	
661									return null;
662								});
663	
664								// #{#eaf3a} Validate OCR results before inserting
665								if (!extracted || !hasUsableOcrData(extracted)) {
666									const msg = `OCR returned no usable data for: ${att.filename} (merchant: ${extracted?.merchant_name ?? 'null'}, amount: ${extracted?.total_amount ?? 'null'})`;
667									console.log(msg);
668									processingErrors.push(msg);
669									continue;
670								}
671	
672								console.log('Inserting receipt from attachment for user:', userId);
673	
674								// Resolve the date and notify on a suspicious/missing date (shared handler).
675								const dateResult = await resolveDateAndNotify(extracted, att.filename);
676	
677								// #{#fcr1a} #{#fcr2a} Fetch exchange rate for foreign currency receipts
678								const exchangeRate = await fetchRateForReceipt(
679									deps.exchangeRate,
680									extracted.currency,
681									extracted.transaction_date
682								);
683	
684								inserted = await insertReceipt(supabase, {
685									user_id: userId,
686									receipt_image_path: path,
687									transaction_date: extracted.transaction_date,
688									total_amount: extracted.total_amount,
689									tax: extracted.tax,
690									merchant_name: extracted.merchant_name,
691									currency: extracted.currency,
692									exchange_rate_to_cad: exchangeRate,
693									credit_card_name: extracted.credit_card_name,
694									credit_card_last_4: extracted.credit_card_last_4,
695									suspicious_date: dateResult.suspicious_date
696								});
697								processedCount++;
698								console.log('Receipt from attachment inserted successfully');
699								// #{#eaf4a} No break — continue processing remaining attachments
700							} catch (e) {
701								const msg = `Attachment error (${att.filename}): ${errText(e)}`;
702								console.error(msg);
703								processingErrors.push(msg);
704							}
705						}
706	
707						console.log(
708							`Processed ${processedCount} receipt(s) from ${attachments.length} attachment(s)`
709						);
710					}
711				} catch (e) {
712					const msg = `Exception fetching attachment URLs: ${errText(e)}`;
713					console.error(msg);
714					processingErrors.push(msg);
715				}
716			}
717		}
