1	/**
2	 * Pure helpers for managing a user's additional email addresses on the profile page.
3	 *
4	 * A profile stores up to five additional emails in fixed columns `email_1` … `email_5`.
5	 * Slots are never shifted: adding fills the first empty slot, deleting sets a slot to NULL.
6	 * These functions are extracted verbatim from `src/routes/profile/+page.svelte` so the
7	 * page logic can be unit tested without a Supabase client.
8	 */
9	
10	/** The five profile columns that hold additional email addresses, in slot order. */
11	export const EMAIL_SLOT_COLUMNS = ['email_1', 'email_2', 'email_3', 'email_4', 'email_5'] as const;
12	
13	export type EmailSlotColumn = (typeof EMAIL_SLOT_COLUMNS)[number];
14	
15	const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
16	
17	/**
18	 * Returns true when the trimmed input looks like a valid email address.
19	 * Matches the page's `emailRegex.test(input.trim())` check.
20	 */
21	export function isValidEmail(email: string): boolean {
22		return EMAIL_REGEX.test(email.trim());
23	}
24	
25	/**
26	 * Case-insensitive duplicate check. The candidate is trimmed and lower-cased, then
27	 * compared against the lower-cased `existing` list (which should already include the
28	 * primary email when guarding against duplicates on the profile page).
29	 */
30	export function isDuplicateEmail(candidate: string, existing: string[]): boolean {
31		const normalized = candidate.trim().toLowerCase();
32		return existing.some((email) => email.toLowerCase() === normalized);
33	}
34	
35	/**
36	 * Index of the first empty slot (null or empty string), or null when all slots are full.
37	 * Mirrors the page's `findIndex((slot) => !slot)` behavior.
38	 */
39	export function firstAvailableSlot(slots: (string | null)[]): number | null {
40		const index = slots.findIndex((slot) => !slot);
41		return index === -1 ? null : index;
42	}
43	
44	/**
45	 * Index of the slot whose value exactly matches `email`, or null when not found.
46	 * Used to map a display-row email back to its underlying `email_N` column for
47	 * edit and delete operations.
48	 */
49	export function slotIndexOfEmail(slots: (string | null)[], email: string): number | null {
50		const index = slots.findIndex((slot) => slot === email);
51		return index === -1 ? null : index;
52	}
53	
54	/**
55	 * The `email_N` column name for a given zero-based slot index, or null when out of range.
56	 */
57	export function slotColumn(index: number): EmailSlotColumn | null {
58		return EMAIL_SLOT_COLUMNS[index] ?? null;
59	}
