2	import type { RequestHandler } from './$types';
3	import { processOcrFromUrl } from '$lib/server/ocrProcessor';
4	
5	/**
6	 * POST /api/ocr/extract
7	 *
8	 * Extracts receipt data from a file URL using OCR
9	 * This endpoint expects the file to already be uploaded to storage
10	 *
11	 * Request body (JSON):
12	 * - fileUrl: Public URL of the file in storage
13	 * - mimeType: MIME type of the file
14	 *
15	 * Response:
16	 * - 200: { success: true, data: ReceiptExtract, mimeType: string }
17	 * - 400: Validation error
18	 * - 500: Processing error
19	 */
20	export const POST: RequestHandler = async ({ request }) => {
21		try {
22			const body = await request.json();
23			const { fileUrl, mimeType } = body;
24	
25			// Validate inputs
26			if (!fileUrl || typeof fileUrl !== 'string') {
27				throw error(400, 'fileUrl is required and must be a string');
28			}
29	
30			if (!mimeType || typeof mimeType !== 'string') {
31				throw error(400, 'mimeType is required and must be a string');
32			}
33	
34			// Process OCR
35			const result = await processOcrFromUrl(fileUrl, mimeType);
36	
37			if (!result.success) {
38				throw error(500, result.error || 'OCR processing failed');
39			}
40	
41			return json({
42				success: true,
43				data: result.data,
44				mimeType: result.mimeType
45			});
46		} catch (err) {
47			console.error('OCR extract API error:', err);
48	
49			// Re-throw SvelteKit errors
50			if (err && typeof err === 'object' && 'status' in err) {
51				throw err;
52			}
53	
54			// Handle other errors
55			const message = err instanceof Error ? err.message : 'Unknown error occurred';
56			throw error(500, `OCR extraction failed: ${message}`);
57		}
58	};
