5		// #{#rdc2a} Verbatim printed date (e.g. "25/06/05"), un-interpreted for re-parsing.
6		raw_date_text: string | null;
7		total_amount: number | null;
8		tax: number | null;
9		merchant_name: string | null;
10		currency: string | null;
11		credit_card_name: string | null;
12		credit_card_last_4: string | null;
13	}
