15	/** The loosely-typed JSON the model returns; every field is validated before use. */
16	interface RawOcrContent {
17		is_receipt?: unknown;
18		transaction_date?: string | null;
19		raw_date_text?: string | null;
20		total_amount?: unknown;
21		tax?: unknown;
22		merchant_name?: string | null;
23		currency?: string | null;
24		credit_card_name?: string | null;
25		credit_card_last_4?: string | null;
26	}
27	
28	/** Read an env var via Deno's global without pulling in Deno's type declarations. */
29	function getEnv(key: string): string | undefined {
30		return (
31			globalThis as { Deno?: { env?: { get?: (k: string) => string | undefined } } }
32		).Deno?.env?.get?.(key);
33	}
34	
35	/**
36	 * Injectable seams for the OCR calls. Optional so production keeps calling these
37	 * with the Deno runtime / global fetch; the webhook shell passes them explicitly
38	 * so the network and env access can be redirected.
39	 */
40	export interface MistralDeps {
41		fetchFn?: typeof fetch;
42		env?: (key: string) => string | undefined;
43	}
44	
45	/** Parse a possibly-string/number/other value into a finite number, or null. */
46	function toNum(v: unknown): number | null {
47		if (typeof v === 'number') return Number.isFinite(v) ? v : null;
48		if (typeof v === 'string') {
49			const n = parseFloat(v.replace(/[^0-9.-]/g, ''));
50			return Number.isFinite(n) ? n : null;
51		}
52		return null;
53	}
