207	/**
208	 * Converts text to an SVG image by rendering it.
209	 * Returns the SVG content as a Uint8Array.
210	 */
211	export async function textToImage(text: string): Promise<Uint8Array> {
212		// Create an SVG representation of the text
213	
214		const maxWidth = 800;
215		const fontSize = 14;
216		const lineHeight = 20;
217		const padding = 20;
218	
219		// Split text into lines that fit within maxWidth
220		const lines = text.split('\n');
221		const height = lines.length * lineHeight + padding * 2;
222	
223		// Create SVG
224		const svgContent = `<?xml version="1.0" encoding="UTF-8"?>
225	<svg width="${maxWidth}" height="${height}" xmlns="http://www.w3.org/2000/svg">
226	  <rect width="100%" height="100%" fill="white"/>
227	  <text x="${padding}" y="${padding + fontSize}" font-family="monospace" font-size="${fontSize}" fill="black">
228	    ${lines.map((line, i) => `<tspan x="${padding}" dy="${i === 0 ? 0 : lineHeight}">${escapeXml(line)}</tspan>`).join('\n    ')}
229	  </text>
230	</svg>`;
231	
232		// Encode the SVG as UTF-8 bytes
233		const encoder = new TextEncoder();
234		return encoder.encode(svgContent);
235	}
236	
237	function escapeXml(unsafe: string): string {
238		return unsafe
239			.replace(/&/g, '&amp;')
240			.replace(/</g, '&lt;')
241			.replace(/>/g, '&gt;')
242			.replace(/"/g, '&quot;')
243			.replace(/'/g, '&apos;');
244	}
